#!/usr/bin/env bash
set -euo pipefail
ROOT="$(pwd)"
SELF="$(basename "$0")"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
MARK='__VISHWAKARMAA_V65_UPDATE_PAYLOAD__'
LINE=$(awk -v m="$MARK" '$0==m {print NR; exit}' "$0")
[ -n "$LINE" ] || { echo 'ERROR: payload marker not found.' >&2; exit 1; }
tail -n +$((LINE+1)) "$0" | base64 -d > "$TMP/update.tar.gz"
for f in android/app/src/main/assets/index.html android/app/build.gradle README.md; do
  if [ -f "$ROOT/$f" ]; then
    mkdir -p "$ROOT/.v65_backup/$(dirname "$f")"
    cp "$ROOT/$f" "$ROOT/.v65_backup/$f"
  fi
done
tar -xzf "$TMP/update.tar.gz" -C "$ROOT"
echo 'Project Vishwakarmaa V65 update applied.'
echo 'Changed: Android launch hub + version 65 + README progress.'
echo 'Backup: .v65_backup/'
echo "Next: git add -A && git commit -m 'V65 mobile pilot launch hub' && git push origin main"
exit 0
$MARK
